<script setup>
import {reactive,ref,watch} from 'vue'
import {onShow,onHide,onUnload} from '@dcloudio/uni-app'
import {operatorSession,operatorToken,clearOperatorSession} from '../../services/operator-session.js'
import {initialDiagnosisState,createAsyncDiagnosisFlow} from '../../services/async-diagnosis.js'
import {ASSESSMENT_EVIDENCE,assessmentMonth,assessmentMonthUtc,createAssessmentPolicyApi,validAssessmentBody} from '../../services/assessment-policies.js'
import {createAssessmentPolicyRecovery} from '../../services/assessment-policy-recovery.js'
import {imageRequestKey} from '../../services/private-images.js'
const fresh=()=>({acquisition:'',coupon:'',requirements:[],grades:[{code:'',label:'',min_score:''},{code:'',label:'',min_score:''}],note:'',from:'',to:'',revision:0})
const state=reactive(initialDiagnosisState()),form=reactive(fresh()),editing=ref(0),selected=ref(null),merchantPage=ref(1),confirmation=ref(null),api=createAssessmentPolicyApi(),blocked=()=>state.busy||state.retry||state.kind==='storage',allowed=()=>operatorSession.canAssessment
const recovery=createAssessmentPolicyRecovery({actor:()=>operatorSession.actorId})
const flow=createAsyncDiagnosisFlow({state,token:operatorToken,allowed,scope:()=>`assessment-policy:${operatorSession.actorId}`,recovery,newKey:imageRequestKey,load:async(t,p)=>{const [policies,merchants]=await Promise.all([api.list(t,p),api.merchants(t,merchantPage.value)]);return {...policies,merchants}},write:api.write,onWritten:clearForm,confirm:action=>new Promise(resolve=>{const q=confirmation.value;uni.showModal({title:action==='discard-local'?'清理本机政策请求':'确认门店考核政策',content:action==='discard-local'?'请核对刚读取的服务器列表。只清理本机请求，不删除政策或历史记录，不自动重新提交。':q?`${q.merchant.name}\n生效月 ${assessmentMonth(q.valid_from)}，截止月 ${assessmentMonth(q.valid_to)}（不含）\n拉新目标 ${q.acquisition_target}，券目标 ${q.coupon_target}\n权重40%／40%／20%；需 ${q.process_requirements.length} 项过程证据、${q.grade_thresholds.length} 档等级\n来源：${q.source_note}\n发布后冻结，只能停止；不追溯历史月份，配置本身不产生分数。`:'请重新读取政策后确认。',success:r=>resolve(r.confirm&&Boolean(q||action==='discard-local')),fail:()=>resolve(false)})})})
let visible=false
function clearForm(){editing.value=0;selected.value=null;confirmation.value=null;Object.assign(form,fresh())}
function choose(m){if(!blocked())selected.value=JSON.parse(JSON.stringify(m))}
function edit(p){if(blocked())return;editing.value=p.id;selected.value=JSON.parse(JSON.stringify(p.merchant));Object.assign(form,{acquisition:String(p.acquisition_target),coupon:String(p.coupon_target),requirements:[...p.process_requirements],grades:JSON.parse(JSON.stringify(p.grade_thresholds)),note:p.source_note,from:assessmentMonth(p.valid_from),to:assessmentMonth(p.valid_to),revision:p.revision})}
function save(){if(blocked())return;const action=editing.value?'update':'create',b={merchant_id:selected.value?.id,acquisition_target:Number(form.acquisition),coupon_target:Number(form.coupon),process_requirements:[...form.requirements],grade_thresholds:JSON.parse(JSON.stringify(form.grades)),source_note:form.note.trim(),valid_from:assessmentMonthUtc(form.from),valid_to:assessmentMonthUtc(form.to),...(editing.value?{expected_revision:form.revision}:{})};if(!/^[1-9]\d{0,6}$/.test(form.acquisition)||!/^[1-9]\d{0,6}$/.test(form.coupon)||!validAssessmentBody(b,action)){state.message='请选择门店并填写正整数目标、必需证据、有效来源和未来月份；等级从高到低、阈值两位小数、末档0.00。';return}confirmation.value=JSON.parse(JSON.stringify({...b,merchant:selected.value}));flow.save(action,editing.value,b)}
function setStatus(p,status){if(blocked())return;confirmation.value=JSON.parse(JSON.stringify(p));flow.save('status',p.id,{expected_revision:p.revision,status})}
function addGrade(){if(!blocked()&&form.grades.length<10)form.grades.push({code:'',label:'',min_score:''})}
function removeGrade(i){if(!blocked()&&form.grades.length>2)form.grades.splice(i,1)}
function sourceNext(delta){if(blocked())return;merchantPage.value+=delta;flow.load(state.page)}
function login(){clearOperatorSession();uni.navigateTo({url:'/pages/operator/login'})}
function reset(){flow.reset();clearForm();merchantPage.value=1}
watch(()=>[operatorSession.accessToken,allowed()],()=>{reset();if(visible&&operatorToken()&&allowed())flow.load()},{flush:'sync'})
watch(()=>state.kind,k=>{if(['unauthorized','forbidden','missing'].includes(k))clearForm()})
onShow(()=>{visible=true;if(operatorToken()&&allowed())flow.load()});onHide(()=>{visible=false;reset()});onUnload(()=>{visible=false;reset()})
</script>
<template><view class="reservation-page">
 <text class="reservation-title">门店月度考核政策</text><text>北京时间自然月，拉新40%／券40%／过程20%。目标与等级须有来源；缺有效依据为未知，不追溯历史成绩。配置本身不产生分数。</text>
 <button v-if="!operatorToken()" @tap="login">运营登录</button><text v-else-if="!allowed()">当前账号没有考核政策权限。</text><template v-else>
  <view v-if="state.data" class="reservation-panel"><text>有效门店来源</text><text v-if="!state.data.merchants.items.length">没有可配置的有效门店。</text><view v-for="m in state.data.merchants.items" :key="m.id"><text>{{m.name}} · {{m.address}}</text><button :disabled="blocked()" @tap="choose(m)">选用此门店</button></view><button v-if="merchantPage>1" :disabled="blocked()" @tap="sourceNext(-1)">上一页门店</button><button v-if="merchantPage*20<state.data.merchants.total" :disabled="blocked()" @tap="sourceNext(1)">下一页门店</button></view>
  <view class="reservation-panel"><text class="reservation-heading">{{editing?'修改政策草稿':'新建政策草稿'}}</text><text>{{selected?`已选 ${selected.name}`:'请先选择门店'}}</text><input v-model="form.acquisition" type="number" maxlength="7" :disabled="blocked()" placeholder="月有效拉新目标 1–1000000"/><input v-model="form.coupon" type="number" maxlength="7" :disabled="blocked()" placeholder="月实际券核销目标 1–1000000"/>
   <text>必需过程证据（至少一项）</text><checkbox-group @change="form.requirements=$event.detail.value"><label v-for="(label,key) in ASSESSMENT_EVIDENCE" :key="key"><checkbox :value="key" :checked="form.requirements.includes(key)" :disabled="blocked()"/>{{label}}</label></checkbox-group>
   <text>等级从高到低配置，末档最低分须0.00，代码及名称不重复</text><view v-for="(grade,i) in form.grades" :key="i"><input v-model="grade.code" maxlength="16" :disabled="blocked()" placeholder="等级代码（大写字母开头）"/><input v-model="grade.label" maxlength="32" :disabled="blocked()" placeholder="等级名称"/><input v-model="grade.min_score" type="digit" maxlength="6" :disabled="blocked()" placeholder="最低分 0.00–100.00"/><button v-if="form.grades.length>2" :disabled="blocked()" @tap="removeGrade(i)">移除此等级</button></view><button v-if="form.grades.length<10" :disabled="blocked()" @tap="addGrade">增加等级</button>
   <input v-model="form.note" maxlength="256" :disabled="blocked()" placeholder="目标、证据及等级的来源说明 2–256 字"/><text>未来完整北京时间月份，截止月不含在内</text><input v-model="form.from" maxlength="7" :disabled="blocked()" placeholder="生效月 YYYY-MM"/><input v-model="form.to" maxlength="7" :disabled="blocked()" placeholder="截止月 YYYY-MM（不含）"/>
   <button :disabled="blocked()||!selected" @tap="save">保存政策草稿</button><button :disabled="blocked()" @tap="clearForm">新建另一草稿</button>
  </view><text v-if="state.message" role="status">{{state.message}}</text><button v-if="['unauthorized','forbidden'].includes(state.kind)" @tap="login">重新登录</button><button v-if="state.retry" :disabled="state.busy" @tap="flow.retry">重试原政策请求</button><button v-if="state.kind==='storage'" :disabled="state.busy" @tap="flow.discardLocal">核对服务器并清理本机请求</button><button :disabled="state.busy" @tap="flow.load(state.page)">刷新政策和门店</button>
  <template v-if="state.data"><text v-if="!state.data.items.length">尚未配置政策，考核规则未知，不使用旧表默认0分。</text><view v-for="p in state.data.items" :key="p.id" class="reservation-panel"><text class="reservation-heading">{{p.merchant.name}} · {{p.status}} · 修订 {{p.revision}}</text><text>{{assessmentMonth(p.valid_from)}} 至 {{assessmentMonth(p.valid_to)}}（截止月不含）</text><text>拉新目标 {{p.acquisition_target}} · 券目标 {{p.coupon_target}} · 固定权重40／40／20</text><text v-for="e in p.process_requirements" :key="e">{{ASSESSMENT_EVIDENCE[e]}}</text><text v-for="g in p.grade_thresholds" :key="g.code">{{g.label}}（{{g.code}}）：总分至少 {{g.min_score}}</text><text>{{p.source_note}}</text><button v-if="p.status==='DRAFT'" :disabled="blocked()" @tap="edit(p)">修改草稿</button><button v-if="p.status==='DRAFT'" :disabled="blocked()" @tap="setStatus(p,'PUBLISHED')">发布并冻结</button><button v-if="p.status==='PUBLISHED'" :disabled="blocked()" @tap="setStatus(p,'STOPPED')">停止政策</button></view><button v-if="state.page>1" :disabled="blocked()" @tap="flow.load(state.page-1)">上一页政策</button><button v-if="state.page*20<state.data.total" :disabled="blocked()" @tap="flow.load(state.page+1)">下一页政策</button></template>
 </template><button v-if="allowed()" @tap="uni.navigateTo({url:'/pages/operator/monthly-assessment'})">门店月度结算与历史</button><button @tap="uni.navigateTo({url:'/pages/operator/review'})">运营工作区</button>
</view></template>
